function TimelineRow({entry:e,locale,now,onClick}:{entry:Entry;locale:Locale;now:number;onClick:()=>void}){
 const zone=useDisplayZone();const dateFormat=(date:string,l:Locale,withTime=false)=>formatInZone(date,l,withTime,zone);const {t,byId}=useCatalog();const future=!!e.startAt&&Date.parse(e.startAt)>now;const date=future?e.startAt:e.endAt||e.startAt;const urgency=deadlineUrgency(e,now);
 return <div className="owner-entry-row"><button className={'timeline-row'+(entryState(e,now)==='ended'?' is-ended':'')+(urgency?' is-urgent '+urgency:'')} onClick={onClick}><span className="timeline-date">{date?dateFormat(date,locale):'—'}<small>{future?t.starts:e.endAt?t.ends:t.starts}</small></span><Picture src={byId[e.gameId].icon||byId[e.gameId].logo} alt=""/><div className="timeline-entry"><span>{byId[e.gameId].name[locale]} · {regionLabel(byId[e.gameId],e.region,locale,t)} · {t[e.kind]}</span><strong>{entryTitle(e,locale)}</strong><PickupBadge entry={e} locale={locale}/></div><span className="timeline-countdown">{urgency&&<em><Clock3 size={12}/>{t.endingUrgent}</em>}<b>{!future&&!e.endAt?t.noEnd:date&&Date.parse(date)>now?countdown(date,now,locale):t.ended}</b>{date&&<small>{dateFormat(date,locale,true)} · {zone}</small>}</span><ChevronRight size={16}/></button><EntryEdit entry={e} locale={locale} compact/></div>;
}
function Sources({entries,checks,locale}:{entries:Entry[];checks:SourceCheck[];locale:Locale}){const zone=useDisplayZone();const dateFormat=(date:string,l:Locale,withTime=false)=>formatInZone(date,l,withTime,zone);const {t,byId,games,editMode,openEditor}=useCatalog();return <div className="sources-panel"><SectionTitle number="01" title={t.syncTitle} note="SOURCE INDEX"/><div className="source-kinds">{(['official','community','video'] as const).map(k=><div key={k}><span>{k==='official'?t.officialNews:k==='community'?t.communityInfo:t.videoInfo}</span><strong>{new Set(entries.flatMap(e=>[...((e.sourceKind||'official')===k?[e.sourceUrl]:[]),...(e.relatedSources||[]).filter(s=>s.kind===k).map(s=>s.url)])).size}</strong></div>)}</div><div className="source-table">{games.map(g=>{const c=checks.find(c=>c.gameId===g.id);const list=entries.filter(e=>e.gameId===g.id);return <div className="source-row" key={g.id}><Picture src={g.logo} alt=""/><div><h3>{g.name[locale]}</h3><span>{g.publisher}</span></div><div className="source-metrics"><strong>{list.length}</strong><span>{t.snapshot}</span></div><div className="source-state" title={c?.error||undefined}><span className={c?.status==='ok'?'online':''}><i/>{c?.status==='ok'?t.connected:c?.status==='error'?t.stale:t.review}</span><small>{c?dateFormat(c.checkedAt,locale,true):'—'}</small></div><a href={g.sources[0].url} target="_blank" rel="noreferrer" aria-label={g.name[locale]+' '+t.openSource}><ArrowUpRight size={20}/></a></div>;})}</div><div className="coverage-note"><Globe2 size={21}/><div><h3>{t.coverage}</h3><p>{t.serverNote} {t.allNote}</p><p>{t.scheduleNote}</p></div></div></div>;}

function PickupBadge({entry:e,locale}:{entry:Entry;locale:Locale}){if(e.kind!=='pickup'&&e.kind!=='weapon')return null;const type=e.pickupType||'unknown';const {t,byId,games,editMode,openEditor}=useCatalog();return <span className={'pickup-badge '+type}>{type==='new'?t.newPickup:type==='rerun'?t.rerunPickup:type==='mixed'?t.mixedPickup:t.unknownPickup}</span>;}
function LocalizationBadge({entry:e,locale}:{entry:Entry;locale:Locale}){const {t}=useCatalog();return e.translatedLocales?.includes(locale)&&!e.officialLocales?.includes(locale)?<span className="localization-label" title={t.sourceLanguage+': '+localeNames[e.sourceLocale||'en']}>{t.translatedTitle}</span>:null;}
function MemberList({entry:e,locale,expanded=false}:{entry:Entry;locale:Locale;expanded?:boolean}){const {t}=useCatalog();if(e.selectionCount&&!expanded)return <span className="selection-summary">{t.selectionCandidates} {e.pickupMembers?.length} · {t.selectionChoose} {e.selectionCount}</span>;return <span className="pickup-members">{e.pickupMembers?.map((m,i)=><span key={i}><b className={'member-type '+m.type}>{m.role==='candidate'?t.selectionCandidates:m.role==='rate-up'?t.rateUp:m.type==='new'?t.newPickup:m.type==='rerun'?t.rerunPickup:t.unknownPickup}</b>{localizedName(m.name,locale)}</span>)}</span>;}
export function PickupSection({group:g,locale,now,saved,onSave,onOpen,weaponEntries}:{weaponEntries:Entry[];group:PickupGroup;locale:Locale;now:number;saved:string[];onSave:(id:string)=>void;onOpen:(e:Entry)=>void}){
 const {t,byId,games,editMode,openEditor}=useCatalog();const game=byId[g.gameId];const members=g.entries.flatMap(e=>featuredMembers(e)||[{type:e.pickupType||'unknown'}]);const added=members.filter(m=>m.type==='new').length;const reruns=members.filter(m=>m.type==='rerun').length;
 const cards=pickupCards(g.entries);
 const [expanded,setExpanded]=useState(false);const weaponPool=g.poolType==='weapon',open=!weaponPool||expanded;const controlId='weapon-pool-'+encodeURIComponent(g.id);
 const pool=g.poolType==='weapon'?t.weaponPool:g.poolType==='support'?t.supportPool:g.poolType==='standard'?t.standardPool:t.characterPool;
 return <section className="pickup-group" style={{'--group-accent':game.color} as CSSProperties}><div className="pickup-group-heading"><div className="pickup-group-title"><Picture src={game.icon||game.logo} alt=""/><div><span>{game.name[locale]} / {regionLabel(game,g.region,locale,t)}</span><h3>{g.entries[0].bannerName?.[locale]||pool}<small>{t.simultaneous}</small></h3></div></div><div className="pickup-group-counts">{added>0&&<span className="new">{t.newPickup} <b>{added}</b></span>}{reruns>0&&<span className="rerun">{t.rerunPickup} <b>{reruns}</b></span>}{g.entries.some(e=>e.selectionCount)&&<span className="selection-summary">{t.selectionChoose} <b>{g.entries.reduce((n,e)=>n+(e.selectionCount||0),0)}</b></span>}<small>{cards.length} {t.banners}</small>{weaponPool&&<button type="button" className="weapon-pool-toggle" aria-expanded={expanded} aria-controls={controlId} onClick={()=>setExpanded(v=>!v)}>{expanded?weaponUi[locale].hide:weaponUi[locale].show}<ChevronDown size={16} style={{transform:expanded?"rotate(180deg)":undefined}}/></button>}</div></div><div id={controlId} hidden={!open}>{open&&<div className="entry-grid pickup-grid">{cards.map(({key,entry,display})=><EntryCard key={key} entry={display} editingEntry={entry} locale={locale} now={now} saved={saved.includes(entry.id)} onSave={()=>onSave(entry.id)} onOpen={()=>onOpen(entry)} weaponLinks={signatureWeapons(display,weaponEntries)} onOpenWeapon={onOpen}/>)}</div>}</div></section>;
}

export function EntryArtwork({entry:e,locale,variant='card',onUnavailable}:{entry:Entry;locale:Locale;variant?:'card'|'detail'|'hero';onUnavailable?:()=>void}){
 const {t,byId,games,editMode,openEditor}=useCatalog();const entity=e.kind==='pickup'||e.kind==='weapon';const displayMembers=variant==='detail'||e.selectionCount?e.pickupMembers:featuredMembers(e);const members=displayMembers?.filter(m=>m.image&&m.imageVerified)||[];
 if(entity&&!editedEntryArtwork(e)&&(displayMembers?.length||0)>1&&members.length>0)return <span className={'entity-artwork art-'+variant+' member-artwork'+(e.selectionCount?' selection-artwork':'')}>{displayMembers?.map((m,i)=><span className="member-art-panel" key={i}>{m.image&&m.imageVerified?<ArtworkMedia locale={locale} serviceLocale={serviceArtworkLocale(e.region,e.gameId)} art={m} alt={m.name[locale]} mode={variant==='detail'?'full':'preview'}/>:<span className="art-pending"><ImageOff size={21}/><span>{t.imagePending}</span></span>}<small>{m.name[locale]}</small></span>)}</span>;
 if(entity&&(!e.image||!artworkForLocale(e,locale,variant==='detail'?'full':'preview',serviceArtworkLocale(e.region,e.gameId)).imageVerified)){
  const images=pickupArtwork(e,locale,variant==='detail'?'full':'preview');if(images.length===1)return <span className={'entity-artwork art-'+variant+' matched-art'}><ArtworkMedia locale={locale} serviceLocale={serviceArtworkLocale(e.region,e.gameId)} art={images[0].art} alt={entryTitle(e,locale)} onUnavailable={onUnavailable} mode={variant==='detail'?'full':'preview'}/></span>;
 }
 if((e.versionHero&&!artworkForLocale(e,locale,'full',serviceArtworkLocale(e.region,e.gameId)).imageVerified)||(entity&&!matchedArtwork(e))||!e.image)return <span className={'entity-artwork art-'+variant+' art-pending'}><ImageOff size={28}/><span>{t.imagePending}</span></span>;
 return <span className={'entity-artwork art-'+variant+(entity?' matched-art':'')+(e.imageKind==='splash'?' full-splash':'')+(e.imageSource?.includes('/portrait/trainee/256/')?' portrait-art':'')}><ArtworkMedia locale={locale} serviceLocale={serviceArtworkLocale(e.region,e.gameId)} art={e} alt={entryTitle(e,locale)} onUnavailable={onUnavailable} fitPreview={entity?'focus':'contain'} mode={variant==='detail'?'full':'preview'}/></span>;
}
function EntryDetails({entry:e,locale}:{entry:Entry;locale:Locale}){const {t,byId,games,editMode,openEditor}=useCatalog();const sources=e.relatedSources||[];return <>
 {e.marketRegion&&<p className="market-note">{e.kind==='package'?t.marketPrice:({ko:'적용 지역',en:'Applicable region',ja:'対象地域',zh:'适用地区'})[locale]}: {t[e.marketRegion]}</p>}
 {!!e.detailSections?.some(s=>displaySection(s.title[locale],s.body[locale]))&&<section className="content-details"><h3>{t.detailsHeading}</h3>{e.detailSections.map((section,i)=>displaySection(section.title[locale],section.body[locale])&&(!section.audienceRegions?.length||section.audienceRegions.includes(audienceMarket(byId[e.gameId],e.region,locale)))&&<div className="detail-section" key={i}><h4>{section.title[locale]}{section.sourceKind==='community'&&<small>{t.communityInfo}</small>}</h4><DetailCopy text={section.body[locale]} locale={locale} gameId={e.gameId}/><EntryEdit entry={e} locale={locale} scope={`section:${i}`} compact/></div>)}</section>}
 {!!detailArtworkForLocale(e,locale).length&&<div className="detail-gallery">{detailArtworkForLocale(e,locale).map(art=><figure key={art.image}><ArtworkMedia art={art} alt={art.imageCaption?.[locale]||entryTitle(e,locale)} locale={locale} serviceLocale={serviceArtworkLocale(e.region,e.gameId)} mode="full"/>{art.imageCaption?.[locale]&&<figcaption>{art.imageCaption[locale]}</figcaption>}<EntryEdit entry={e} locale={locale} scope={(e.detailImages?.findIndex(a=>a.image===art.image)??-1)>=0?`detail-image:${e.detailImages!.findIndex(a=>a.image===art.image)}`:'image'} compact/></figure>)}</div>}
 <ContentBlocks entry={e} locale={locale}/></>;}
